class Solution { public long findScore(int[] nums){Integer[] order=new Integer[nums.length];for(int i=0;i<nums.length;i++)order[i]=i;Arrays.sort(order,(a,b)->nums[a]!=nums[b]?Integer.compare(nums[a],nums[b]):Integer.compare(a,b));boolean[] marked=new boolean[nums.length];long score=0;for(int index:order)if(!marked[index]){score+=nums[index];marked[index]=true;if(index>0)marked[index-1]=true;if(index+1<nums.length)marked[index+1]=true;}return score;} }
